#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    // In-place LU factorization (Doolittle, no pivoting):
    // A(i,j) for i <= j stores U(i,j)
    // A(i,j) for i >  j stores L(i,j), with implicit L(i,i)=1

    if (N == 0) return;

    for (size_t k = 0; k < N; ++k) {
        // Compute U(k, j) for j = k..N-1
        #pragma omp parallel for schedule(static)
        for (size_t j = k; j < N; ++j) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) {
                sum += A[k * N + p] * A[p * N + j];
            }
            A[k * N + j] -= sum;
        }

        // Compute L(i, k) for i = k+1..N-1
        // Uses U(k,k) already computed above.
        const double pivot = A[k * N + k];
        #pragma omp parallel for schedule(static)
        for (size_t i = k + 1; i < N; ++i) {
            double sum = 0.0;
            for (size_t p = 0; p < k; ++p) {
                sum += A[i * N + p] * A[p * N + k];
            }
            A[i * N + k] = (A[i * N + k] - sum) / pivot;
        }
    }
}
